const { ethers } = require('ethers');
const fs = require('fs');
const path = require('path');
require('dotenv').config();

// Contract ABI (Application Binary Interface)
const CONTRACT_ABI = [
  "function registerReport(bytes32 _reportHash, string memory _reportId) public",
  "function verifyReport(bytes32 _reportHash) public view returns (bool exists, uint256 timestamp, address uploader, string memory reportId)",
  "function getTotalReports() public view returns (uint256)",
  "function getHashByIndex(uint256 index) public view returns (bytes32)"
];

// Contract Bytecode (compiled contract)
// This is a simplified version - in production, compile with Hardhat/Truffle
const CONTRACT_BYTECODE = ""; // Placeholder

async function deployContract() {
  console.log('🚀 Deploying ThreatIntelRegistry to Ethereum Sepolia Testnet...\n');

  try {
    // Check environment variables
    const rpcUrl = process.env.ETHEREUM_RPC_URL;
    const privateKey = process.env.ETHEREUM_PRIVATE_KEY;

    if (!rpcUrl) {
      throw new Error('ETHEREUM_RPC_URL not found in .env file');
    }
    if (!privateKey) {
      throw new Error('ETHEREUM_PRIVATE_KEY not found in .env file');
    }

    // Connect to Sepolia testnet via provided RPC (Alchemy/Infura)
    const provider = new ethers.JsonRpcProvider(rpcUrl);

    // Create wallet
    const wallet = new ethers.Wallet(privateKey, provider);
    console.log('📍 Deploying from address:', wallet.address);

    // Check balance
    const balance = await provider.getBalance(wallet.address);
    console.log('💰 Balance:', ethers.formatEther(balance), 'ETH');

    if (balance === 0n) {
      console.log('\n⚠️  WARNING: No ETH balance!');
      console.log('Get free Sepolia ETH from:');
      console.log('   - https://sepoliafaucet.com/');
      console.log('   - https://www.infura.io/faucet/sepolia');
      console.log('\nSend to:', wallet.address);
      return;
    }

    console.log('\n📝 Note: For this environment, use a pre-deployed contract or deploy manually');
    console.log('Contract deployment requires compilation with Hardhat or Remix');
    console.log('\nFor now, you can:');
    console.log('1. Deploy via Remix IDE: https://remix.ethereum.org');
    console.log('2. Copy the contract from contracts/ThreatIntelRegistry.sol');
    console.log('3. Deploy to Sepolia testnet');
    console.log('4. Copy the contract address to .env as ETHEREUM_CONTRACT_ADDRESS');

    // Save deployment info template
    const deploymentInfo = {
      network: 'sepolia',
      contractName: 'ThreatIntelRegistry',
      deployerAddress: wallet.address,
      instructions: 'Deploy contract manually via Remix and update .env with contract address'
    };

    fs.writeFileSync(
      path.join(__dirname, '../ethereum-deployment.json'),
      JSON.stringify(deploymentInfo, null, 2)
    );

    console.log('\n✅ Deployment info saved to ethereum-deployment.json');

  } catch (error) {
    console.error('\n❌ Deployment failed:', error.message);
    process.exit(1);
  }
}

// Generate a new wallet if needed
function generateWallet() {
  const wallet = ethers.Wallet.createRandom();
  console.log('\n🔑 New Ethereum Wallet Generated:');
  console.log('Address:', wallet.address);
  console.log('Private Key:', wallet.privateKey);
  console.log('\n⚠️  IMPORTANT: Save this private key securely!');
  console.log('Add to .env file as: ETHEREUM_PRIVATE_KEY=' + wallet.privateKey);
  console.log('\nGet free Sepolia testnet ETH from:');
  console.log('   - https://sepoliafaucet.com/');
  console.log('   - https://www.infura.io/faucet/sepolia');
}

// Check command line arguments
const args = process.argv.slice(2);
if (args.includes('--generate-wallet')) {
  generateWallet();
} else {
  deployContract();
}
